  "violations": [
    {
      "subject": "alpha",
      "tenant": "globex",
      "access": "read"
    },
    {
      "subject": "bravo",
      "tenant": "acme",
      "access": "read"
    }
  ],
  "assumptions": "The stated grants are authoritative: alpha may access only acme, and bravo may access only globex. Per the supplied oracle, cross-tenant writes rejected by business logic without state changes remain UNKNOWN, despite HTTP 200, and are not listed as confirmed violations.",
  "rationale": "Both cross-tenant reads returned HTTP 200 and the other tenant's stored order state, establishing unauthorized access. The successful accesses within each principal's granted tenant do not violate isolation."
}

